from pathlib import Path
import json,hashlib,runpy
import numpy as np
from PIL import Image

root=Path(__file__).resolve().parent;kit=root/'kit'
m=json.loads((kit/'manifest.json').read_text());issues=[]
source=np.array(Image.open(kit/m['original']).convert('RGB'))
union=np.zeros(source.shape[:2],bool)
ids={a['id'] for a in m['assets']}
if {p.stem for p in (kit/'stickers').glob('*.png')}!=ids:issues.append('Orphan or missing master PNG')
source_identical=hashlib.sha256((kit/m['original']).read_bytes()).hexdigest()==hashlib.sha256((root.parents[2]/'月下温泉.png').read_bytes()).hexdigest()
if not source_identical:issues.append('Original file differs from user source')
for a in m['assets']:
    im=Image.open(kit/a['file']);ar=np.array(im)
    if im.mode!='RGBA' or list(im.size)!=a['pixel_size_wh']:issues.append(a['id']+': master dimensions/mode')
    if ar[0,:,3].any() or ar[-1,:,3].any() or ar[:,0,3].any() or ar[:,-1,3].any():issues.append(a['id']+': master touches export border')
    mask=np.array(Image.open(kit/a['original_visible_mask']).convert('L'))>0;union|=mask
    for path in [a['file'],a['native_complete_file']]+[p['file'] for p in a['render_parts']]:
        img=Image.open(kit/path);rgba=np.array(img)
        if img.mode!='RGBA':issues.append(path+': RGBA required');continue
        if rgba[rgba[:,:,3]==0,:3].any():issues.append(path+': nonzero RGB beneath zero alpha')
    native=Image.open(kit/a['native_complete_file'])
    if native.size!=tuple(round(n) for n in a['logical_size_wh']):issues.append(a['id']+': full native dimensions')
    for part in a['render_parts']:
        if part['kind']=='source_visible_overlay':
            rgba=np.array(Image.open(kit/part['file']));x,y=map(round,part['origin_xy']);h,w=rgba.shape[:2];visible=rgba[:,:,3]>0
            if not np.array_equal(rgba[:,:,:3][visible],source[y:y+h,x:x+w][visible]):issues.append(a['id']+': source overlay RGB changed')
    if not set(a.get('occluder_ids',[])).issubset(ids):issues.append(a['id']+': unknown occluder')
fixed_excludes=True
for p in m.get('fixed_foreground_parts',[]):
    rgba=np.array(Image.open(kit/p['file']));mask=rgba[:,:,3]>0
    if (mask&union).any():issues.append('Fixed foreground contains active source pixels');fixed_excludes=False
    if not np.array_equal(rgba[:,:,:3][mask],source[mask]):issues.append('Fixed foreground differs from source')
    if rgba[~mask,:3].any():issues.append('Fixed foreground transparent RGB')
fn=runpy.run_path(str(kit/'reconstruct.py'))['reconstruct'];rebuilt=np.array(fn(kit));saved=np.array(Image.open(kit/m['reconstructed']).convert('RGB'))
repeat_equal=np.array_equal(rebuilt,saved)
if not repeat_equal:issues.append('Saved assembly does not match manifest reconstruction')
if not np.array_equal(saved[union],source[union]):issues.append('Source-visible union is not restored exactly')
report={'ok':not issues,'logical_asset_count':len(ids),'errors':issues,
        'master_rgba_and_transparent_border_checked':True,'zero_alpha_rgb_checked':True,
        'original_byte_identical':source_identical,'source_visible_rgb_checked':True,
        'fixed_foreground_excludes_active_subjects':fixed_excludes,'reconstruction_repeat_pixel_equal':repeat_equal,
        'source_visible_restored_pixels':int(union.sum())}
(kit/'quality/artifact-check.json').write_text(json.dumps(report,ensure_ascii=False,indent=2))
print(json.dumps(report,ensure_ascii=False));raise SystemExit(0 if report['ok'] else 1)
#!/usr/bin/env python3
"""Rebuild the snap-position scene from the saved manifest and bound parts."""
import argparse,json
from pathlib import Path
from PIL import Image

def reconstruct(root):
    m=json.loads((root/'manifest.json').read_text())
    out=Image.open(root/m['base']).convert('RGBA')
    parts=[p for a in m['assets'] for p in a['render_parts']]+m.get('fixed_foreground_parts',[])
    for p in sorted(parts,key=lambda p:p['z']):
        im=Image.open(root/p['file']).convert('RGBA')
        wh=tuple(max(1,round(v)) for v in p['size_wh'])
        if im.size!=wh: im=im.resize(wh,Image.Resampling.LANCZOS)
        out.alpha_composite(im,tuple(round(v) for v in p['origin_xy']))
    return out.convert('RGB')

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--kit',type=Path,default=Path(__file__).resolve().parent);p.add_argument('--output',type=Path)
    a=p.parse_args();dest=a.output or a.kit/'reconstructed.png';reconstruct(a.kit).save(dest);print(dest)
